CREATE COLUMN TABLE "TEST_AP"."OWST" ("WstCode" INTEGER CS_INT NOT NULL , "Name" NVARCHAR(20) NOT NULL , "Remarks" NVARCHAR(100), "MaxReqr" SMALLINT CS_INT DEFAULT 1, "UserSign" SMALLINT CS_INT, "MaxRejReqr" SMALLINT CS_INT DEFAULT 1, PRIMARY KEY ("WstCode")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OWST_NAME" ON "TEST_AP"."OWST" ( "Name" ASC )